	/* struct gce_cmds (:54-62): the u64 arrays are 8-aligned under AAPCS */
	ck_u64("gce_cmds size", sizeof(struct gce_cmds), 0xe808);
	ck_u64("gce_cmds addr", offsetof(struct gce_cmds, addr), 0x800);
