	ck_u64("probe log size", probe[P_LOG_SIZE], 0x400);

	/* ioctl numbers: probe (kernel header + asm-generic _IOC) == mtk_vcu_abi.h == literal */
	ck_u64("req SET_OBJECT", MTK_VCU_SET_OBJECT, 0x40587600u);
	ck_u64("req MVA_ALLOCATION", MTK_VCU_MVA_ALLOCATION, 0xc0207601u);
