/* ---------------------------------------------------------------- requests and open/close */

static void t_requests(void)
{
	struct env *e = &g_env;
	struct n2vcu_stats s;

	ck("env_init", env_init(e) == 0);
	ck("dev path", strcmp(n2vcu_dev(e->v)->path, "/dev/vcu") == 0);
	ck("vpu path", strcmp(n2vcu_dev_vpu(e->v)->path, "/dev/vpu") == 0);
	ck("dev ctx is the model", n2vcu_dev(e->v)->ctx == e->v);

	/* mtk_vcu.c:1966-1968: an unmatched request falls to default and returns ret = -1. */
	ck_i64("unknown request -> -EPERM", dev_ioctl(e, 0x12345678u, SHARE_A), -EPERM);
	/* mtk_vcu.c:1805-1812: the switch matches the whole number, so a wrong _IOC size is unknown. */
	ck_i64("SET_OBJECT wrong size -> -EPERM", dev_ioctl(e, 0x40587604u, SHARE_A), -EPERM);
	ck_i64("GET_OBJECT wrong size -> -EPERM", dev_ioctl(e, 0xc0587608u, SHARE_A), -EPERM);
	s = stats_of(e);
	ck_u64("unknown_requests counted", s.unknown_requests, 3);

	/* open/close counting (mtk_vcu.c:1503-1594) */
	ck("second open", e->dev->open(e->dev->ctx, 2) == 0);
	ck("first close", e->dev->close(e->dev->ctx) == 0);
	ck("last close", e->dev->close(e->dev->ctx) == 0);
	e->opened = 0;
	env_fini(e);
}

/* ---------------------------------------------------------------- VCU_SET_OBJECT / VCU_GET_OBJECT */

static unsigned h_calls;
static int h_last_id;
static uint32_t h_last_len;
static char h_last_buf[MTK_VCU_SHARE_BUF_SIZE + 1];
static int h_modify;
static int h_ret;

static int test_handler(void *ctx, int id, void *buf, uint32_t len)
{
	(void)ctx;
	h_calls++;
	h_last_id = id;
	h_last_len = len;
	memcpy(h_last_buf, buf, len < MTK_VCU_SHARE_BUF_SIZE ? len : MTK_VCU_SHARE_BUF_SIZE);
	if (h_modify)
		((uint8_t *)buf)[0] = 0x5a;
	return h_ret;
}

static void put_share(struct n2a32_cpu *c, uint32_t at, int32_t id, uint32_t len, const char *text)
{
	put32(c, at, (uint32_t)id);
	put32(c, at + 4, len);
	if (text)
		put_bytes(c, at + 8, text, (uint32_t)strlen(text));
}

static void t_ipi(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;
	struct n2vcu_stats s;
	char buf[8];

	ck("env_init", env_init(e) == 0);
	h_calls = 0;
	h_modify = 0;
	h_ret = 0;
	ck("register VENC_H264", n2vcu_ap_register(e->v, MTK_IPI_VENC_H264, test_handler, NULL) == 0);
	ck("register VDEC_H264", n2vcu_ap_register(e->v, MTK_IPI_VDEC_H264, test_handler, NULL) == 0);
	ck_i64("register bad id", n2vcu_ap_register(e->v, MTK_IPI_MAX, test_handler, NULL), -EINVAL);
	ck_i64("register null handler", n2vcu_ap_register(e->v, 3, NULL, NULL), -EINVAL);

	/* SET_OBJECT: mtk_vcu.c:1805-1823, handler call at :1400-1414 */
	put_share(c, SHARE_A, MTK_IPI_VENC_H264, 4, "ABCD");
	ck_i64("SET_OBJECT returns 0", dev_ioctl(e, MTK_VCU_SET_OBJECT, SHARE_A), 0);
	ck_u64("handler called once", h_calls, 1);
	ck_u64("handler id", (uint64_t)h_last_id, MTK_IPI_VENC_H264);
	ck_u64("handler len", h_last_len, 4);
	ck("handler buf", memcmp(h_last_buf, "ABCD", 4) == 0);
	ck("guest share_obj unchanged", get32(c, SHARE_A) == MTK_IPI_VENC_H264);

	/* The kernel copies the (possibly modified) share_obj back, mtk_vcu.c:1817-1821. */
	h_modify = 1;
	put_share(c, SHARE_A, MTK_IPI_VENC_H264, 4, "ABCD");
	ck_i64("SET_OBJECT modified", dev_ioctl(e, MTK_VCU_SET_OBJECT, SHARE_A), 0);
	ck_u64("handler modification visible in guest", n2a32_ld8(c, SHARE_A + 8), 0x5a);
	h_modify = 0;

	/* id range: mtk_vcu.c:1806-1812 */
	h_calls = 0;
	put_share(c, SHARE_A, MTK_IPI_MAX, 4, "x");
	ck_i64("SET_OBJECT id 50 -> -EINVAL", dev_ioctl(e, MTK_VCU_SET_OBJECT, SHARE_A), -EINVAL);
	put_share(c, SHARE_A, -1, 4, "x");
	ck_i64("SET_OBJECT id -1 -> -EINVAL", dev_ioctl(e, MTK_VCU_SET_OBJECT, SHARE_A), -EINVAL);
	ck_u64("handler not called for bad ids", h_calls, 0);
	/* an in-range id with no handler still returns 0 (copy_to_user overwrites ret, :1814-1816) */
	put_share(c, SHARE_A, MTK_IPI_VENC_H265, 4, "x");
	ck_i64("SET_OBJECT no handler -> 0", dev_ioctl(e, MTK_VCU_SET_OBJECT, SHARE_A), 0);
	put_share(c, SHARE_A, MTK_IPI_VCU_INIT, 4, "x");
	ck_i64("SET_OBJECT IPI_VCU_INIT -> 0", dev_ioctl(e, MTK_VCU_SET_OBJECT, SHARE_A), 0);
	/* a len larger than the share buffer is clamped before the handler (memory safety) */
	put_share(c, SHARE_A, MTK_IPI_VENC_H264, 200, "y");
	h_calls = 0;
	ck_i64("SET_OBJECT bogus len accepted", dev_ioctl(e, MTK_VCU_SET_OBJECT, SHARE_A), 0);
	ck_u64("bogus len clamped to 80", h_last_len, 80);

	/* AP -> daemon: vcu_ipi_send() mtk_vcu.c:388-400 */
	ck_i64("ap_send id 0 -> -EINVAL", n2vcu_ap_send(e->v, MTK_IPI_VCU_INIT, "x", 1), -EINVAL);
	ck_i64("ap_send id 50 -> -EINVAL", n2vcu_ap_send(e->v, MTK_IPI_MAX, "x", 1), -EINVAL);
	ck_i64("ap_send len 81 -> -EINVAL", n2vcu_ap_send(e->v, 15, "x", 81), -EINVAL);
	ck_i64("ap_send null buf -> -EINVAL", n2vcu_ap_send(e->v, 15, NULL, 1), -EINVAL);

	ck_i64("ap_send 15", n2vcu_ap_send(e->v, MTK_IPI_VENC_H264, "WXYZ", 4), 0);
	ck_u64("pending 15", n2vcu_ap_pending(e->v, MTK_IPI_VENC_H264), 1);
	put_share(c, SHARE_A, MTK_IPI_VENC_H264, 0, NULL);
	ck_i64("GET_OBJECT 15", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), 0);
	ck_u64("GET_OBJECT id", get32(c, SHARE_A), MTK_IPI_VENC_H264);
	ck_u64("GET_OBJECT len", get32(c, SHARE_A + 4), 4);
	get_bytes(c, SHARE_A + 8, buf, 4);
	ck("GET_OBJECT payload", memcmp(buf, "WXYZ", 4) == 0);
	ck_u64("pending after get", n2vcu_ap_pending(e->v, MTK_IPI_VENC_H264), 0);
	n2vcu_set_get_timeout_ms(e->v, 0);
	ck_i64("GET_OBJECT empty -> -ETIMEDOUT", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), -ETIMEDOUT);
	ck_i64("wait_dispatched after get", n2vcu_ap_wait_dispatched(e->v, 15, 0), 0);

	/* instance mapping: mtk_vcu.c:478-483 / ipi_id_to_inst_id :118-125 */
	ck_i64("ap_send dec 3", n2vcu_ap_send(e->v, MTK_IPI_VDEC_H264, "DEC!", 4), 0);
	put_share(c, SHARE_A, MTK_IPI_VENC_H264, 0, NULL);
	ck_i64("GET VENC does not see VDEC", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), -ETIMEDOUT);
	put_share(c, SHARE_A, MTK_IPI_VDEC_H264, 0, NULL);
	ck_i64("GET VDEC gets it", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), 0);
	get_bytes(c, SHARE_A + 8, buf, 4);
	ck("GET VDEC payload", memcmp(buf, "DEC!", 4) == 0);

	/* overwrite: the kernel keeps one user_obj per instance (mtk_vcu.c:421-426) */
	ck_i64("ap_send one", n2vcu_ap_send(e->v, 15, "one", 3), 0);
	ck_i64("ap_send two", n2vcu_ap_send(e->v, 15, "two", 3), 0);
	put_share(c, SHARE_A, 15, 0, NULL);
	ck_i64("GET after overwrite", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), 0);
	get_bytes(c, SHARE_A + 8, buf, 3);
	ck("last message wins", memcmp(buf, "two", 3) == 0);
	s = stats_of(e);
	ck_u64("ipi_overwritten", s.ipi_overwritten, 1);

	/* every VENC id shares one queue (mtk_vcu.c:118-125, user_obj[2]): V41's QUERY_CAP on
	 * IPI_VENC_COMMON and INIT on the codec id must not overtake each other */
	ck_i64("ap_send VENC_COMMON", n2vcu_ap_send(e->v, MTK_IPI_VENC_COMMON, "A", 1), 0);
	ck_i64("ap_send VENC_H264 after it", n2vcu_ap_send(e->v, MTK_IPI_VENC_H264, "B", 1), 0);
	put_share(c, SHARE_A, MTK_IPI_VENC_COMMON, 0, NULL);
	ck_i64("GET COMMON", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), 0);
	ck_u64("the later id holds the shared slot", get32(c, SHARE_A), MTK_IPI_VENC_H264);
	/* the kernel does not range-check the id the daemon passes to GET_OBJECT */
	ck_i64("ap_send for a garbage id", n2vcu_ap_send(e->v, 15, "G", 1), 0);
	put_share(c, SHARE_A, -12345, 0, NULL);
	ck_i64("GET with a garbage id fetches the VENC slot",
	       dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), 0);
	ck_u64("garbage-id fetch", get32(c, SHARE_A), MTK_IPI_VENC_H264);

	/* the ACK is only raised for id > IPI_VCU_INIT and handler return 0 (mtk_vcu.c:1403-1410) */
	ck("register IPI_VCU_INIT", n2vcu_ap_register(e->v, MTK_IPI_VCU_INIT, test_handler, NULL) == 0);
	s = stats_of(e);
	h_ret = 0;
	put_share(c, SHARE_A, MTK_IPI_VENC_H264, 1, "a");
	ck_i64("SET for ack", dev_ioctl(e, MTK_VCU_SET_OBJECT, SHARE_A), 0);
	ck_u64("ack counted", stats_of(e).ipi_acks, s.ipi_acks + 1);
	h_ret = -1;
	put_share(c, SHARE_A, MTK_IPI_VENC_H264, 1, "a");
	ck_i64("SET without ack", dev_ioctl(e, MTK_VCU_SET_OBJECT, SHARE_A), 0);
	ck_u64("no ack counted", stats_of(e).ipi_acks, s.ipi_acks + 1);
	h_ret = 0;
	put_share(c, SHARE_A, MTK_IPI_VCU_INIT, 1, "a");
	ck_i64("SET id 0 with handler", dev_ioctl(e, MTK_VCU_SET_OBJECT, SHARE_A), 0);
	ck_u64("IPI_VCU_INIT is never acked", stats_of(e).ipi_acks, s.ipi_acks + 1);

	/* interruptible by stop_request (the kernel's wait_event_freezable returns -ERESTARTSYS) */
	put_share(c, SHARE_A, MTK_IPI_VENC_H264, 0, NULL);
	ck_i64("ap_send for interrupt", n2vcu_ap_send(e->v, 15, "irq", 3), 0);
	n2vcu_set_get_timeout_ms(e->v, 5000);
	ck_i64("GET consumes", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), 0);
	e->cpu.stop_request = 1;
	ck_i64("GET interrupted -> -EINTR", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), -EINTR);
	e->cpu.stop_request = 0;

	/* abort breaks the waits too */
	ck_i64("ap_send for abort", n2vcu_ap_send(e->v, 15, "abt", 3), 0);
	ck_i64("GET consumes 2", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), 0);
	n2vcu_abort(e->v);
	ck_i64("GET aborted -> -EINTR", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), -EINTR);

	env_fini(e);
}

struct sender_arg {
	struct n2vcu *v;
	int ipi_id;
	unsigned delay_ms;
	const char *text;
};

static void *sender_thread(void *p)
{
	struct sender_arg *a = (struct sender_arg *)p;

	sleep_ms(a->delay_ms);
	n2vcu_ap_send(a->v, a->ipi_id, a->text, (uint32_t)strlen(a->text));
	return NULL;
}

static void t_ipi_thread(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;
	struct sender_arg a;
	pthread_t th;
	int64_t t0, dt;
	char buf[8];

	ck("env_init", env_init(e) == 0);
	n2vcu_set_get_timeout_ms(e->v, 5000);
	a.v = e->v;
	a.ipi_id = MTK_IPI_VENC_H265;
	a.delay_ms = 30;
	a.text = "THRD";
	ck("thread create", pthread_create(&th, NULL, sender_thread, &a) == 0);
	put_share(c, SHARE_A, MTK_IPI_VENC_H265, 0, NULL);
	t0 = now_ms_test();
	ck_i64("GET blocks until the AP sends", dev_ioctl(e, MTK_VCU_GET_OBJECT, SHARE_A), 0);
	dt = now_ms_test() - t0;
	pthread_join(th, NULL);
	ck("GET waited at least 20 ms", dt >= 20);
	ck("GET did not wait a full second", dt < 1000);
	get_bytes(c, SHARE_A + 8, buf, 4);
	ck("threaded payload", memcmp(buf, "THRD", 4) == 0);
	env_fini(e);
}

/* ---------------------------------------------------------------- allocation, free, cache */

static void put_mem_obj(struct n2a32_cpu *c, uint32_t at, uint64_t iova, uint32_t len, uint64_t pa,
			uint64_t va)
{
	put64(c, at, iova);
	put32(c, at + 8, len);
	put32(c, at + 12, 0);
	put64(c, at + 16, pa);
	put64(c, at + 24, va);
}

static struct fhw_dma *fhw_buf_for_pa(struct fhw *f, uint32_t pa)
{
	unsigned i;

	for (i = 0; i < FHW_MAX_DMA; i++)
		if (f->dma[i].used && f->dma[i].pa == pa)
			return &f->dma[i];
	return NULL;
}

static void t_alloc(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;
	struct n2vcu_stats s;
	struct fhw_dma *d;
	uint64_t pa1, va1, mva, mva_va;

	ck("env_init", env_init(e) == 0);

	/* VCU_PA_ALLOCATION -> mtk_vcu_get_page(), mtk_vcodec_mem.c:205-224 */
	put_mem_obj(c, MEM_A, 0, 0x2000, 0, 0);
	ck_i64("PA_ALLOCATION", dev_ioctl(e, MTK_VCU_PA_ALLOCATION, MEM_A), 0);
	ck_u64("PA len", get32(c, MEM_A + 8), 0x2000);
	pa1 = get64(c, MEM_A + 16);
	va1 = get64(c, MEM_A + 24);
	ck("PA pa nonzero", pa1 != 0);
	ck("PA iova == pa (task contract)", get64(c, MEM_A) == pa1);
	ck("PA va is a guest address", va1 != 0 && va1 != ~(uint64_t)0);
	ck_u64("fake dma_alloc called", e->f.dma_allocs, 1);
	ck_u64("PA buffer zeroed", get32(c, (uint32_t)va1), 0);

	/* Cache maintenance only sees vb2 (MVA) buffers, mtk_vcodec_mem.c:394-410. */
	put_bytes(c, (uint32_t)va1, "Q", 1);
	put_mem_obj(c, MEM_B, pa1, 0x2000, pa1, va1);
	ck_i64("CACHE_FLUSH_BUFF on a PA buffer -> -EINVAL",
	       dev_ioctl(e, MTK_VCU_CACHE_FLUSH_BUFF, MEM_B), -EINVAL);

	/* VCU_MVA_ALLOCATION -> mtk_vcu_get_buffer(), mtk_vcodec_mem.c:160-199 */
	put_mem_obj(c, MEM_A, 0, 0x1000, 0, 0);
	ck_i64("MVA_ALLOCATION", dev_ioctl(e, MTK_VCU_MVA_ALLOCATION, MEM_A), 0);
	ck_u64("MVA len", get32(c, MEM_A + 8), 0x1000);
	mva = get64(c, MEM_A);
	mva_va = get64(c, MEM_A + 24);
	ck("MVA iova == pa", mva == get64(c, MEM_A + 16));
	ck("MVA va is a guest address", mva_va != 0 && mva_va != ~(uint64_t)0);
	ck_u64("fake dma_allocs 2", e->f.dma_allocs, 2);
	d = fhw_buf_for_pa(&e->f, (uint32_t)mva);
	ck("MVA buffer found in the fake", d != NULL);

	/* n2vc_dma_sync(): write through the guest mirror, then flush it to the back end. */
	put_bytes(c, (uint32_t)mva_va, "Q", 1);
	put_mem_obj(c, MEM_A, mva, 0x1000, mva, mva_va);
	ck_i64("CACHE_FLUSH_BUFF", dev_ioctl(e, MTK_VCU_CACHE_FLUSH_BUFF, MEM_A), 0);
	ck_u64("flush copied to the fake buffer", d ? d->buf[0] : 0, 'Q');
	if (d)
		d->buf[1] = 'R';
	ck_i64("CACHE_INVALIDATE_BUFF", dev_ioctl(e, MTK_VCU_CACHE_INVALIDATE_BUFF, MEM_A), 0);
	ck_u64("invalidate copied to the guest", n2a32_ld8(c, (uint32_t)mva_va + 1u), 'R');
	/* range checks: mtk_vcodec_mem.c:398-410 */
	put_mem_obj(c, MEM_A, mva + 0x1000, 0x2000, 0, 0);
	ck_i64("CACHE_FLUSH_BUFF out of range -> -EINVAL",
	       dev_ioctl(e, MTK_VCU_CACHE_FLUSH_BUFF, MEM_A), -EINVAL);
	/* CACHE_FLUSH_ALL flushes every vb2 buffer and nothing else (mtk_vcodec_mem.c:358-392) */
	s = stats_of(e);
	ck_i64("CACHE_FLUSH_ALL", dev_ioctl(e, MTK_VCU_CACHE_FLUSH_ALL, 0), 0);
	ck_u64("flush all synced exactly the vb2 buffer", stats_of(e).cache_syncs, s.cache_syncs + 1);

	/* free: va, iova and len must all match (mtk_vcodec_mem.c:252-256) */
	put_mem_obj(c, MEM_B, mva, 0x800, mva, mva_va);
	ck_i64("MVA_FREE wrong len -> -EINVAL", dev_ioctl(e, MTK_VCU_MVA_FREE, MEM_B), -EINVAL);
	put_mem_obj(c, MEM_B, mva, 0x1000, mva, mva_va);
	ck_i64("MVA_FREE", dev_ioctl(e, MTK_VCU_MVA_FREE, MEM_B), 0);
	ck_u64("free zeroes iova", get64(c, MEM_B), 0);
	ck_u64("free zeroes pa", get64(c, MEM_B + 16), 0);
	ck_u64("free zeroes va", get64(c, MEM_B + 24), 0);
	ck_u64("fake dma_free called", e->f.dma_frees, 1);
	s = stats_of(e);
	ck_i64("CACHE_FLUSH_ALL with one PA buffer left", dev_ioctl(e, MTK_VCU_CACHE_FLUSH_ALL, 0), 0);
	ck_u64("PA buffers are not synced", stats_of(e).cache_syncs, s.cache_syncs);

	/* free with iova == 0 && va == 0 -> -EINVAL (mtk_vcu.c:1882-1887) */
	put_mem_obj(c, MEM_B, 0, 0x10, 0, 0);
	ck_i64("FREE with zero iova/va -> -EINVAL", dev_ioctl(e, MTK_VCU_PA_FREE, MEM_B), -EINVAL);

	/* PA free compares pa and va only (mtk_vcodec_mem.c:292-296) */
	put_mem_obj(c, MEM_B, 0, 0, pa1, va1 + 1u);
	ck_i64("PA_FREE wrong va -> -EINVAL", dev_ioctl(e, MTK_VCU_PA_FREE, MEM_B), -EINVAL);
	put_mem_obj(c, MEM_B, 0, 0x1234, pa1, va1);
	ck_i64("PA_FREE ignores len", dev_ioctl(e, MTK_VCU_PA_FREE, MEM_B), 0);
	ck_u64("fake dma_frees 2", e->f.dma_frees, 2);

	/* invalid lengths: mtk_vcodec_mem.c:167-172 */
	put_mem_obj(c, MEM_A, 0, 0, 0, 0);
	ck_i64("alloc len 0 -> -EINVAL", dev_ioctl(e, MTK_VCU_PA_ALLOCATION, MEM_A), -EINVAL);
	ck_u64("failure fields are -1 (iova)", get64(c, MEM_A), ~(uint64_t)0);
	ck_u64("failure fields are -1 (pa)", get64(c, MEM_A + 16), ~(uint64_t)0);
	ck_u64("failure fields are -1 (va)", get64(c, MEM_A + 24), ~(uint64_t)0);
	put_mem_obj(c, MEM_A, 0, 0x8000001, 0, 0);
	ck_i64("alloc > 128 MiB -> -EINVAL", dev_ioctl(e, MTK_VCU_PA_ALLOCATION, MEM_A), -EINVAL);
	ck_u64("big failure fields are -1", get64(c, MEM_A + 24), ~(uint64_t)0);

	/* back end failure -> -ENOMEM and the same -1 fields (mtk_vcu.c:1841-1853) */
	e->f.fail_alloc = 1;
	put_mem_obj(c, MEM_A, 0, 0x1000, 0, 0);
	ck_i64("dma_alloc failure -> -ENOMEM", dev_ioctl(e, MTK_VCU_MVA_ALLOCATION, MEM_A), -ENOMEM);
	ck_u64("ENOMEM fields are -1", get64(c, MEM_A), ~(uint64_t)0);
	e->f.fail_alloc = 0;

	/* CODEC_MAX_BUFFER: the 513th live allocation is refused (mtk_vcodec_mem.c:167-172) */
	{
		unsigned i;

		for (i = 0; i < 512; i++) {
			put_mem_obj(c, MEM_A, 0, 0x1000, 0, 0);
			if (dev_ioctl(e, MTK_VCU_MVA_ALLOCATION, MEM_A) != 0)
				break;
		}
		ck_u64("512 allocations accepted", i, 512);
		put_mem_obj(c, MEM_A, 0, 0x1000, 0, 0);
		ck_i64("513th allocation -> -EINVAL", dev_ioctl(e, MTK_VCU_MVA_ALLOCATION, MEM_A), -EINVAL);
	}
	ck("last close frees every buffer", e->dev->close(e->dev->ctx) == 0);
	e->opened = 0;
	ck_u64("all DMA buffers freed", e->f.dma_frees, e->f.dma_allocs);
	ck_u64("all guest maps dropped", dreg_used(), 0);
	env_fini(e);
}

/* ---------------------------------------------------------------- mmap: register windows, DMEM, DMA */

static uint32_t win_word(struct fhw *f, unsigned win, uint32_t off)
{
	return f->reg[win][off / 4];
}

static void t_mmap_regs(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;
	struct n2vcu_stats s;
	uint32_t a, a2, b, c1;
	uint32_t dmem = 0, dlen = 0;
	int err;

	ck("env_init", env_init(e) == 0);

	/* mtk_vcu_mmap(): + vcu_check_reg_base(), mtk_vcu.c:1653-1720, :679-693 */
	a = dev_mmap(e, 0x40000, 0x16000000u, &err);
	ck("VDEC window mmap", a != 0 && err == 0);
	ck_u64("VDEC guest is 1 MiB aligned", a & 0xfffffu, 0);
	put32(c, a, 0x12345678u);
	ck_u64("VDEC_BASE[0]", win_word(&e->f, RWVC_WIN_VDEC_BASE, 0), 0x12345678u);
	ck_u64("read back through MMIO", get32(c, a), 0x12345678u);
	put32(c, a + 0x20000u, 0xaaaa0001u);
	ck_u64("VDEC_VLD[0]", win_word(&e->f, RWVC_WIN_VDEC_VLD, 0), 0xaaaa0001u);
	put32(c, a + 0x2f000u, 0xfeed0002u);
	ck_u64("VDEC_SYS[0]", win_word(&e->f, RWVC_WIN_VDEC_SYS, 0), 0xfeed0002u);
	put32(c, a + 0x25010u, 0xcccc0003u);
	ck_u64("VDEC_MISC[0x10]", win_word(&e->f, RWVC_WIN_VDEC_MISC, 0x10), 0xcccc0003u);
	/* sub-word access to a register: read-modify-write on the aligned word */
	put32(c, a + 0x2f004u, 0xaabbccddu);
	n2a32_st8(c, a + 0x2f004u, 0x5a);
	ck_u64("byte store merges", win_word(&e->f, RWVC_WIN_VDEC_SYS, 4), 0xaabbcc5au);
	ck_u64("byte load extracts", n2a32_ld8(c, a + 0x2f005u), 0xcc);
	ck_u64("halfword load extracts", n2a32_ld16(c, a + 0x2f004u), 0xcc5au);
	/* an unaligned 32-bit access straddles two register words; defined as a byte access here
	 * (real Device memory would fault, and the kernel ABI only allows 4-aligned offsets) */
	put32(c, a + 0x2f008u, 0x11223344u);
	put32(c, a + 0x2f00cu, 0x55667788u);
	ck_u64("straddling 32-bit load", n2a32_ld32(c, a + 0x2f009u), 0x88112233u);
	n2a32_st32(c, a + 0x2f009u, 0xdeadbeefu);
	ck_u64("straddling store, low word", win_word(&e->f, RWVC_WIN_VDEC_SYS, 8), 0xadbeef44u);
	ck_u64("straddling store, high word", win_word(&e->f, RWVC_WIN_VDEC_SYS, 0xc), 0x556677deu);
	ck_u64("straddling 32-bit read back", n2a32_ld32(c, a + 0x2f009u), 0xdeadbeefu);

	/* vcu_check_reg_base() rejects anything outside the three windows */
	err = 0;
	ck_u64("window length beyond VDEC -> 0", dev_mmap(e, 0x80000, 0x16000000u, &err), 0);
	ck_i64("errno EINVAL", err, EINVAL);
	ck_u64("mmap 0x15000000 -> 0", dev_mmap(e, 0x1000, 0x15000000u, &err), 0);
	ck_u64("mmap 0x40000000 -> 0", dev_mmap(e, 0x1000, 0x40000000u, &err), 0);
	ck_u64("mmap len 0 -> 0", dev_mmap(e, 0, 0x16000000u, &err), 0);

	/* VENC 0x17020000+0x10000 is a VCU window but the RWVC window is only 0x2000 */
	b = dev_mmap(e, 0x10000, 0x17020000u, &err);
	ck("VENC window mmap", b != 0 && err == 0);
	put32(c, b + 0x10u, 0x55u);
	ck_u64("VENC[0x10]", win_word(&e->f, RWVC_WIN_VENC, 0x10), 0x55u);
	s = stats_of(e);
	put32(c, b + 0x2000u, 0x66u);   /* outside RWVC_WIN_VENC */
	ck_u64("out-of-window access counted", stats_of(e).mmio_bad, s.mmio_bad + 1);
	ck_u64("last bad mmio address", stats_of(e).last_bad_mmio_addr, 0x17022000u);

	c1 = dev_mmap(e, 0x10000, 0x17820000u, &err);
	ck("VENC_C1 window mmap", c1 != 0 && err == 0);
	put32(c, c1 + 8u, 0x77u);
	ck_u64("VENC_C1[8]", win_word(&e->f, RWVC_WIN_VENC_C1, 8), 0x77u);

	/* a second mapping of the same window gets its own guest range and hook */
	a2 = dev_mmap(e, 0x40000, 0x16000000u, &err);
	ck("second VDEC mmap", a2 != 0 && a2 != a);

	/* MAP_SHMEM_ALLOC/COMMIT: the 0x80000-byte DMEM (mtk_vcu.c:1704-1712, :2542) */
	ck_i64("n2vcu_dmem", n2vcu_dmem(e->v, &dmem, &dlen), 0);
	ck_u64("DMEM size", dlen, 0x80000);
	ck("DMEM guest nonzero", dmem != 0);
	ck_u64("mmap 0x80000000", dev_mmap(e, 0x1000, 0x80000000u, &err), dmem);
	put32(c, dmem + 0x40u, 0xdeadc0deu);
	ck("map_dm_addr", n2vcu_map_dm_addr(e->v, dmem + 0x40u) ==
			      (void *)(e->mem->base + dmem + 0x40u));
	ck_u64("DMEM content through the host pointer", *(uint32_t *)n2vcu_map_dm_addr(e->v, dmem + 0x40u),
		0xdeadc0deu);
	ck("map_dm_addr(0) == NULL", n2vcu_map_dm_addr(e->v, 0) == NULL);
	ck("map_dm_addr(below) == NULL", n2vcu_map_dm_addr(e->v, dmem - 1u) == NULL);
	ck("map_dm_addr(base+len) != NULL (kernel: off > len)", n2vcu_map_dm_addr(e->v, dmem + dlen) != NULL);
	ck("map_dm_addr(base+len+1) == NULL", n2vcu_map_dm_addr(e->v, dmem + dlen + 1u) == NULL);
	ck_u64("mmap 0x88001000", dev_mmap(e, 0x1000, 0x88001000u, &err), dmem + 0x1000u);

	env_fini(e);
}

static void t_mmap_dma(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;
	uint64_t pa, va, iova;
	uint32_t g;
	int err;

	ck("env_init", env_init(e) == 0);
	put_mem_obj(c, MEM_A, 0, 0x2000, 0, 0);
	ck_i64("PA alloc for mmap", dev_ioctl(e, MTK_VCU_PA_ALLOCATION, MEM_A), 0);
	pa = get64(c, MEM_A + 16);
	va = get64(c, MEM_A + 24);
	iova = get64(c, MEM_A);

	/* mtk_vcu.c:1668-1684: the mmap right after a PA allocation maps that pa */
	g = dev_mmap(e, 0x2000, pa, &err);
	ck_u64("mmap of the allocated pa", g, va);
	ck("map_buf_pa consumed", err == 0);

	/* eVideoMemMAP() passes the bare pa; the model also resolves it without the flag */
	g = dev_mmap(e, 0x2000, pa, &err);
	ck_u64("mmap of a bare pa", g, va);
	ck("bare pa err", err == 0);
	ck_u64("mmap of the iova", dev_mmap(e, 0x2000, iova, &err), va);

	/* unknown pa -> EINVAL; a register window still wins when the flag names something else */
	ck_u64("mmap unknown pa -> 0", dev_mmap(e, 0x1000, 0xdead0000u, &err), 0);
	ck_i64("unknown pa err", err, EINVAL);

	/* R1 finding F14: a 64-bit offset must not wrap a shmem range (the model compares
	 * offset - BASE with subtraction, never offset + len) */
	ck_u64("mmap offset 0xfffffffffffff000 -> 0",
	       dev_mmap(e, 0x1000, 0xfffffffffffff000ull, &err), 0);
	ck_i64("wrapping offset err", err, EINVAL);
	ck_u64("mmap offset UINT64_MAX -> 0", dev_mmap(e, 0x1000, ~(uint64_t)0, &err), 0);
	/* an iova above 32 bits would otherwise be truncated onto another buffer */
	ck_u64("mmap iova 0x100000000 -> 0", dev_mmap(e, 0x1000, 0x300000000ull, &err), 0);
	put_mem_obj(c, MEM_A, 0, 0x1000, 0, 0);
	ck_i64("PA alloc 2", dev_ioctl(e, MTK_VCU_PA_ALLOCATION, MEM_A), 0);
	ck("register mmap after a PA allocation still works",
	   dev_mmap(e, 0x40000, 0x16000000u, &err) != 0);

	/* F14 boundaries: the last page of every MAP_SHMEM_* range is still accepted, one byte
	 * less of headroom is rejected, and nothing past the end is. */
	{
		uint32_t dmem = 0, dlen = 0, g2, g3;

		ck_i64("dmem for the F14 boundaries", n2vcu_dmem(e->v, &dmem, &dlen), 0);
		ck_u64("ALLOC last page",
		       dev_mmap(e, 0x1000, 0x80000000ull + 0x80000ull - 0x1000ull, &err), dmem + 0x7f000u);
		ck_u64("ALLOC last page + 1 -> 0",
		       dev_mmap(e, 0x1000, 0x80000000ull + 0x80000ull - 0xfffull, &err), 0);
		ck_u64("ALLOC end -> 0", dev_mmap(e, 0x1000, 0x80000000ull + 0x80000ull, &err), 0);
		ck_u64("COMMIT last page",
		       dev_mmap(e, 0x1000, 0x88000000ull + 0x80000ull - 0x1000ull, &err), dmem + 0x7f000u);
		ck_u64("COMMIT last page + 1 -> 0",
		       dev_mmap(e, 0x1000, 0x88000000ull + 0x80000ull - 0xfffull, &err), 0);

		g2 = n2a32_mem_alloc(e->mem, 0x1000, 0x1000);
		ck("synthetic guest for the PA boundary", g2 != 0);
		dreg_synthetic(0xfffff000u, g2, 0x1000);
		ck_u64("PA last page", dev_mmap(e, 0x1000, 0x800000000ull + 0xfffff000ull, &err), g2);
		ck_u64("PA past the last page -> 0",
		       dev_mmap(e, 0x1000, 0x800000000ull + 0x100000000ull - 0xfffull, &err), 0);
		ck_u64("PA end -> 0", dev_mmap(e, 0x1000, 0x900000000ull, &err), 0);

		g3 = n2a32_mem_alloc(e->mem, 0x1000, 0x1000);
		ck("synthetic guest for the MM boundary", g3 != 0);
		dreg_synthetic(0x12345000u, g3, 0x1000);
		ck_u64("MM iova mapping", dev_mmap(e, 0x1000, 0x200000000ull + 0x12345000ull, &err), g3);
		ck_u64("MM last page needs 0x1000 of headroom",
		       dev_mmap(e, 0x1000, 0x200000000ull + 0x1ffffffffull - 0x800ull, &err), 0);
		ck_u64("MM past the end -> 0",
		       dev_mmap(e, 0x1000, 0x200000000ull + 0x200000000ull, &err), 0);
	}

	/* n2vc_dma_lookup_pa() fallback: a buffer this model did not allocate (V41's registry) */
	{
		uint32_t guest = n2a32_mem_alloc(e->mem, 0x1000, 0x1000);

		ck("synthetic guest alloc", guest != 0);
		dreg_synthetic(0xcaf00000u, guest, 0x1000);
		g = dev_mmap(e, 0x100, 0xcaf00000u, &err);
		ck_u64("mmap through n2vc_dma_lookup_pa", g, guest);
		ck_u64("mmap at MAP_SHMEM_PA_BASE + pa", dev_mmap(e, 0x100, 0x800000000ull + 0xcaf00000ull, &err),
		       guest);
	}
	env_fini(e);
}

/* ---------------------------------------------------------------- log ioctls, SET_MMAP_TYPE */

static void t_log(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;
	char text[32];
	int i;

	ck("env_init", env_init(e) == 0);
	for (i = 0; i < 0x400; i++)
		n2a32_st8(c, LOG_A + (uint32_t)i, 0);

	/* VCU_GET_LOG_OBJECT blocks until a log is pending: mtk_vcu.c:528-533 is
	 * wait_event_freezable(vdec_log_get_wq, atomic_read(&vdec_log_got)).  The AP side of the
	 * kernel's vcu_set_log() (:2113-2147) is n2vcu_ap_set_log().  The blocking itself is in
	 * t_log_block(); here a log is always set first so the calls return at once. */
	ck_i64("ap_set_log", n2vcu_ap_set_log(e->v, "ap-log"), 0);
	ck_i64("GET_LOG_OBJECT after set_log", dev_ioctl(e, MTK_VCU_GET_LOG_OBJECT, LOG_A), 0);
	ck("ap log text", memcmp(n2a32_ptr(e->mem, LOG_A), "ap-log", 7) == 0);
	ck_u64("log_sets after ap_set_log", stats_of(e).log_sets, 1);
	ck_u64("log_gets after the first get", stats_of(e).log_gets, 1);
	ck_u64("a pending log does not wait", stats_of(e).log_waits, 0);

	/* VCU_SET_LOG_OBJECT is the guest-side peer of GET in the model (the kernel has no case for
	 * it, see STATUS); it stores the bytes and raises the same flag */
	memset(text, 0, sizeof(text));
	memcpy(text, "mtk-vcu-log", 11);
	put_bytes(c, LOG_A, text, 12);
	ck_i64("SET_LOG_OBJECT exact", dev_ioctl(e, MTK_VCU_SET_LOG_OBJECT, LOG_A), 0);
	ck_i64("SET_LOG_OBJECT other size", dev_ioctl(e, 0x4010760cu, LOG_A), 0);
	ck_i64("GET_LOG_OBJECT again", dev_ioctl(e, MTK_VCU_GET_LOG_OBJECT, LOG_A), 0);
	ck("log text returned", memcmp(n2a32_ptr(e->mem, LOG_A), "mtk-vcu-log", 11) == 0);
	ck_u64("log_sets", stats_of(e).log_sets, 3);
	ck_u64("log_gets", stats_of(e).log_gets, 2);
	/* a smaller _IOC size touches only that many guest bytes (struct log_test is undefined) */
	put_bytes(c, LOG_A + 0x40u, text, 12);
	ck_i64("SET_LOG_OBJECT for the size test", dev_ioctl(e, MTK_VCU_SET_LOG_OBJECT, LOG_A + 0x40u), 0);
	for (i = 0; i < 16; i++)
		n2a32_st8(c, LOG_A + 0x40u + (uint32_t)i, 0xaa);
	ck_i64("GET_LOG_OBJECT with size 4", dev_ioctl(e, 0x4004760bu, LOG_A + 0x40u), 0);
	ck_u64("four bytes copied", get32(c, LOG_A + 0x40u), 0x2d6b746du);   /* "mtk-" */
	ck_u64("byte past the size untouched", n2a32_ld8(c, LOG_A + 0x44u), 0xaa);

	/* VCU_SET_MMAP_TYPE: accepted, map_obj read by layout (mtk_vcu_controls.h:39-43) */
	put32(c, MAP_A, 1);
	put32(c, MAP_A + 4, 3);
	put64(c, MAP_A + 8, 0);
	ck_i64("SET_MMAP_TYPE", dev_ioctl(e, MTK_VCU_SET_MMAP_TYPE, MAP_A), 0);
	ck_u64("map_types", stats_of(e).map_types, 1);
	env_fini(e);
}

/* ---------------------------------------------------------------- blocking GET_LOG_OBJECT */

struct logthr {
	struct env *e;
	struct n2a32_cpu cpu;
	uint32_t arg;
	int rc;
	int done;
};

static void *log_thread(void *p)
{
	struct logthr *a = (struct logthr *)p;
	int rc = a->e->dev->ioctl(a->e->dev->ctx, &a->cpu, MTK_VCU_GET_LOG_OBJECT, a->arg);

	__atomic_store_n(&a->rc, rc, __ATOMIC_RELEASE);
	__atomic_store_n(&a->done, 1, __ATOMIC_RELEASE);
	return NULL;
}

static void t_log_block(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;
	struct n2vcu_stats s;
	struct logthr t;
	pthread_t th;
	int64_t t0, dt;
	char text[2000];

	ck("env_init", env_init(e) == 0);
	ck_u64("log_waits starts at 0", stats_of(e).log_waits, 0);

	/* A log that is already pending is returned at once (the kernel's wait tests the condition
	 * before it sleeps, mtk_vcu.c:528-529). */
	ck_i64("ap_set_log before GET", n2vcu_ap_set_log(e->v, "first-log"), 0);
	t0 = now_ms_test();
	ck_i64("GET with a pending log", dev_ioctl(e, MTK_VCU_GET_LOG_OBJECT, LOG_A), 0);
	dt = now_ms_test() - t0;
	ck("pending log returned immediately", dt < 100);
	ck("pending log text", memcmp(n2a32_ptr(e->mem, LOG_A), "first-log", 10) == 0);
	ck_u64("no wait counted for a pending log", stats_of(e).log_waits, 0);

	/* n2vcu_ap_set_log() mirrors mtk_vcu_write(): 1023 bytes and a forced NUL at :2123. */
	ck_i64("ap_set_log NULL text -> -EINVAL", n2vcu_ap_set_log(e->v, NULL), -EINVAL);
	ck_i64("ap_set_log NULL vcu -> -EINVAL", n2vcu_ap_set_log(NULL, "x"), -EINVAL);
	memset(text, 'A', sizeof(text) - 1);
	text[sizeof(text) - 1] = '\0';
	ck_i64("ap_set_log 1999 bytes", n2vcu_ap_set_log(e->v, text), 0);
	ck_i64("GET the long log", dev_ioctl(e, MTK_VCU_GET_LOG_OBJECT, LOG_A), 0);
	ck_u64("long log byte 0", n2a32_ld8(c, LOG_A), 'A');
	ck_u64("long log byte 1022", n2a32_ld8(c, LOG_A + 1022u), 'A');
	ck_u64("long log NUL at 1023", n2a32_ld8(c, LOG_A + 1023u), 0);

	/* Blocks for 300 ms; n2vcu_ap_set_log() releases it with the new text (the kernel's
	 * wake_up in mtk_vcu_write(), :2141-2142). */
	memset(&t, 0, sizeof(t));
	t.e = e;
	t.arg = LOG_B;
	n2a32_cpu_init(&t.cpu, e->mem);
	ck("thread create 1", pthread_create(&th, NULL, log_thread, &t) == 0);
	sleep_ms(300);
	ck("GET still blocked after 300 ms", __atomic_load_n(&t.done, __ATOMIC_ACQUIRE) == 0);
	ck_u64("one GET blocked (gauge)", stats_of(e).log_blocked, 1);
	t0 = now_ms_test();
	ck_i64("ap_set_log releases it", n2vcu_ap_set_log(e->v, "second-log"), 0);
	ck("thread join 1", pthread_join(th, NULL) == 0);
	dt = now_ms_test() - t0;
	ck_i64("blocked GET rc", __atomic_load_n(&t.rc, __ATOMIC_ACQUIRE), 0);
	ck("set_log released it within 200 ms", dt <= 200);
	ck("set_log text delivered", memcmp(n2a32_ptr(e->mem, LOG_B), "second-log", 11) == 0);
	ck_u64("one waiting GET counted", stats_of(e).log_waits, 1);
	ck_u64("gauge back to 0 after the release", stats_of(e).log_blocked, 0);

	/* vdec_log_got is cleared after the copy (:542): a second GET with no new log blocks, and
	 * the calling cpu's stop_request returns -EINTR within 200 ms (wait_event_freezable ->
	 * -ERESTARTSYS on a signal). */
	memset(&t, 0, sizeof(t));
	t.e = e;
	t.arg = LOG_B;
	n2a32_cpu_init(&t.cpu, e->mem);
	ck("thread create 2", pthread_create(&th, NULL, log_thread, &t) == 0);
	sleep_ms(150);
	ck("second GET blocks (flag cleared)", __atomic_load_n(&t.done, __ATOMIC_ACQUIRE) == 0);
	t0 = now_ms_test();
	__atomic_store_n(&t.cpu.stop_request, 1u, __ATOMIC_RELEASE);
	ck("thread join 2", pthread_join(th, NULL) == 0);
	dt = now_ms_test() - t0;
	ck_i64("stop_request -> -EINTR", __atomic_load_n(&t.rc, __ATOMIC_ACQUIRE), -EINTR);
	ck("stop_request released it within 200 ms", dt <= 200);

	/* A device close wakes a blocked GET_LOG (the file the ioctl belongs to is gone). */
	memset(&t, 0, sizeof(t));
	t.e = e;
	t.arg = LOG_B;
	n2a32_cpu_init(&t.cpu, e->mem);
	ck("thread create 3", pthread_create(&th, NULL, log_thread, &t) == 0);
	sleep_ms(100);
	ck("third GET blocked", __atomic_load_n(&t.done, __ATOMIC_ACQUIRE) == 0);
	t0 = now_ms_test();
	ck("device close", e->dev->close(e->dev->ctx) == 0);
	ck("thread join 3", pthread_join(th, NULL) == 0);
	dt = now_ms_test() - t0;
	ck_i64("close -> -EINTR", __atomic_load_n(&t.rc, __ATOMIC_ACQUIRE), -EINTR);
	ck("close released it within 200 ms", dt <= 200);
	ck("re-open after close", e->dev->open(e->dev->ctx, 2) == 0);

	/* n2vcu_abort() breaks the wait permanently, like the GET_OBJECT waits. */
	memset(&t, 0, sizeof(t));
	t.e = e;
	t.arg = LOG_B;
	n2a32_cpu_init(&t.cpu, e->mem);
	ck("thread create 4", pthread_create(&th, NULL, log_thread, &t) == 0);
	sleep_ms(100);
	ck("fourth GET blocked", __atomic_load_n(&t.done, __ATOMIC_ACQUIRE) == 0);
	n2vcu_abort(e->v);
	ck("thread join 4", pthread_join(th, NULL) == 0);
	ck_i64("abort -> -EINTR", __atomic_load_n(&t.rc, __ATOMIC_ACQUIRE), -EINTR);
	ck_i64("GET after abort -> -EINTR", dev_ioctl(e, MTK_VCU_GET_LOG_OBJECT, LOG_A), -EINTR);
	s = stats_of(e);
	ck("four blocked GETs counted", s.log_waits >= 4);
	env_fini(e);
}

/* n2vcu_destroy() must wake a blocked GET_LOG and not free the context under it. */
static void t_log_destroy(void)
{
	static struct env e;
	struct logthr t;
	pthread_t th;
	struct n2a32_mem *mem;
	int64_t t0, dt;

	ck("env_init (destroy wake)", env_init(&e) == 0);
	mem = e.mem;
	memset(&t, 0, sizeof(t));
	t.e = &e;
	t.arg = LOG_A;
	n2a32_cpu_init(&t.cpu, e.mem);
	ck("thread create 5", pthread_create(&th, NULL, log_thread, &t) == 0);
	sleep_ms(100);
	ck("fifth GET blocked", __atomic_load_n(&t.done, __ATOMIC_ACQUIRE) == 0);
	t0 = now_ms_test();
	n2vcu_destroy(e.v);   /* wakes it and waits for it to leave */
	dt = now_ms_test() - t0;
	ck("thread join 5", pthread_join(th, NULL) == 0);
	ck_i64("destroy -> -EINTR", __atomic_load_n(&t.rc, __ATOMIC_ACQUIRE), -EINTR);
	ck("destroy waited for the waiter and returned", dt <= 500);
	e.v = NULL;
	e.dev = NULL;
	e.opened = 0;
	n2a32_mem_destroy(mem);
	e.mem = NULL;
}

/* ---------------------------------------------------------------- GCE */

static void cmds_reset(struct env *e)
{
	memset(n2a32_ptr(e->mem, CMDS_A), 0, sizeof(struct gce_cmds));
}

static void cmd_set(struct n2a32_cpu *c, unsigned i, unsigned op, uint64_t addr, uint64_t data,
		    uint32_t mask)
{
	n2a32_st8(c, CMDS_A + i, (uint8_t)op);
	n2a32_st64(c, CMDS_A + 0x800u + 8u * i, addr);
	n2a32_st64(c, CMDS_A + 0x4800u + 8u * i, data);
	n2a32_st32(c, CMDS_A + 0x8800u + 4u * i, mask);
}

static void cmd_count(struct n2a32_cpu *c, uint32_t n) { n2a32_st32(c, CMDS_A + 0xe800u, n); }

static int gce_flush(struct env *e, uint64_t handle, uint32_t codec, uint32_t core, uint32_t secure)
{
	put64(&e->cpu, CMDQ_A, CMDS_A);
	put64(&e->cpu, CMDQ_A + 8, handle);
	put32(&e->cpu, CMDQ_A + 0x10, 0);
	put32(&e->cpu, CMDQ_A + 0x14, codec);
	put32(&e->cpu, CMDQ_A + 0x18, core);
	put32(&e->cpu, CMDQ_A + 0x1c, secure);
	return dev_ioctl(e, MTK_VCU_GCE_SET_CMD_FLUSH, CMDQ_A);
}

static int gce_wait(struct env *e, uint64_t handle, uint32_t codec)
{
	put64(&e->cpu, GCE_A, handle);
	put32(&e->cpu, GCE_A + 8, 0);
	put32(&e->cpu, GCE_A + 12, codec);
	return dev_ioctl(e, MTK_VCU_GCE_WAIT_CALLBACK, GCE_A);
}

static void t_gce_cmds(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;
	struct n2vcu_stats s;

	ck("env_init", env_init(e) == 0);

	/* CMD_WRITE: vcu_set_gce_cmd() case :704-711, cmdq_pkt_write() with mask 0xffffffff */
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x17020010u, 0xdeadbeefu, 0xffffffffu);
	cmd_count(c, 1);
	ck_i64("GCE write", gce_flush(e, 0x100, VCU_VENC, 0, 0), 0);
	ck_u64("one op", e->f.nops, 1);
	ck_u64("op is WRITE", e->f.ops[0].op, RWVC_OP_WRITE);
	ck_u64("op window VENC", e->f.ops[0].win, RWVC_WIN_VENC);
	ck_u64("op offset", e->f.ops[0].off, 0x10);
	ck_u64("op value", e->f.ops[0].value, 0xdeadbeefu);
	ck_u64("register written", win_word(&e->f, RWVC_WIN_VENC, 0x10), 0xdeadbeefu);

	/* CMD_WRITE with a mask -> RWVC_OP_WRITE_MASK */
	cmds_reset(e);
	e->f.reg[RWVC_WIN_VENC][0x14 / 4] = 0xffff0000u;
	cmd_set(c, 0, CMD_WRITE, 0x17020014u, 0x12340000u, 0xffff0000u);
	cmd_count(c, 1);
	ck_i64("GCE masked write", gce_flush(e, 0x101, VCU_VENC, 0, 0), 0);
	ck_u64("masked write value", win_word(&e->f, RWVC_WIN_VENC, 0x14), 0x12340000u);

	/* CMD_READ: :702-707, cmdq_pkt_read_addr() into the GCE scratch register */
	cmds_reset(e);
	e->f.reg[RWVC_WIN_VENC][0x18 / 4] = 0x11223344u;
	cmd_set(c, 0, CMD_READ, 0x17020018u, 0, 0);
	cmd_count(c, 1);
	ck_i64("GCE read", gce_flush(e, 0x102, VCU_VENC, 0, 0), 0);
	ck_u64("read op recorded", e->f.ops[e->f.nops - 1].op, RWVC_OP_READ);

	/* CMD_POLL_REG: :715-722, cmdq_pkt_poll_addr(value=data, mask) */
	cmds_reset(e);
	cmd_set(c, 0, CMD_POLL_REG, 0x1702001cu, 0x4u, 0x4u);
	cmd_count(c, 1);
	ck_i64("GCE poll", gce_flush(e, 0x103, VCU_VENC, 0, 0), 0);
	ck_u64("poll op", e->f.ops[e->f.nops - 1].op, RWVC_OP_POLL);
	ck_u64("poll value", e->f.ops[e->f.nops - 1].value, 4);
	ck_u64("poll mask", e->f.ops[e->f.nops - 1].mask, 4);
	e->f.poll_fail = 1;
	cmds_reset(e);
	cmd_set(c, 0, CMD_POLL_REG, 0x1702001cu, 0x4u, 0x4u);
	cmd_count(c, 1);
	ck_i64("GCE poll timeout propagates", gce_flush(e, 0x104, VCU_VENC, 0, 0), -ETIMEDOUT);

	/* CMD_WAIT_EVENT: :740-751, cmdq_pkt_wfe() -> hw->wait_irq */
	cmds_reset(e);
	cmd_set(c, 0, CMD_WAIT_EVENT, 0, VENC_EOF, 0);
	cmd_count(c, 1);
	e->f.irq_fire[RWVC_IRQ_VENC] = 1;
	ck_i64("wait VENC_EOF", gce_flush(e, 0x105, VCU_VENC, 0, 0), 0);
	ck_u64("irq line VENC", e->f.last_irq, RWVC_IRQ_VENC);
	cmds_reset(e);
	cmd_set(c, 0, CMD_WAIT_EVENT, 0, VENC_EOF_C1, 0);
	cmd_count(c, 1);
	e->f.irq_fire[RWVC_IRQ_VENC_C1] = 1;
	ck_i64("wait VENC_EOF_C1", gce_flush(e, 0x106, VCU_VENC, 0, 0), 0);
	ck_u64("irq line VENC_C1", e->f.last_irq, RWVC_IRQ_VENC_C1);
	cmds_reset(e);
	cmd_set(c, 0, CMD_WAIT_EVENT, 0, VDEC_LAT_EVENT_2, 0);
	cmd_count(c, 1);
	e->f.irq_fire[RWVC_IRQ_VDEC_LAT] = 1;
	ck_i64("wait VDEC_LAT_EVENT_2", gce_flush(e, 0x107, VCU_VDEC, 0, 0), 0);
	ck_u64("irq line VDEC_LAT", e->f.last_irq, RWVC_IRQ_VDEC_LAT);
	cmds_reset(e);
	cmd_set(c, 0, CMD_WAIT_EVENT, 0, VDEC_EVENT_3, 0);
	cmd_count(c, 1);
	e->f.irq_fire[RWVC_IRQ_VDEC] = 1;
	ck_i64("wait VDEC_EVENT_3", gce_flush(e, 0x108, VCU_VDEC, 0, 0), 0);
	ck_u64("irq line VDEC", e->f.last_irq, RWVC_IRQ_VDEC);
	/* event >= GCE_EVENT_MAX is dropped (mtk_vcu.c:746-751) */
	cmds_reset(e);
	cmd_set(c, 0, CMD_WAIT_EVENT, 0, 64, 0);
	cmd_count(c, 1);
	s = stats_of(e);
	ck_i64("wait event 64 ignored", gce_flush(e, 0x109, VCU_VENC, 0, 0), 0);
	ck_u64("event 64 skipped", stats_of(e).gce_skipped, s.gce_skipped + 1);
	/* timeout */
	cmds_reset(e);
	cmd_set(c, 0, CMD_WAIT_EVENT, 0, VENC_EOF, 0);
	cmd_count(c, 1);
	n2vcu_set_irq_timeout_ms(e->v, 0);
	ck_i64("wait event timeout", gce_flush(e, 0x10a, VCU_VENC, 0, 0), -ETIMEDOUT);
	n2vcu_set_irq_timeout_ms(e->v, 1000);

	/* addresses outside the VCU map window are skipped, not errors (:704-711, :715-722) */
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x16001000u, 1, 0xffffffffu);   /* DEC04: VDEC_ALL page 0x1000 */
	cmd_set(c, 1, CMD_WRITE, 0x17040000u, 1, 0xffffffffu);   /* outside every VCU window */
	cmd_set(c, 2, CMD_WRITE, 0x40000000u, 1, 0xffffffffu);   /* >= MAP_PA_BASE_1GB */
	cmd_count(c, 3);
	s = stats_of(e);
	{
		unsigned nops = e->f.nops;

		ck_i64("bad addresses skipped", gce_flush(e, 0x10b, VCU_VENC, 0, 0), 0);
		ck_u64("one op for the DEC04 page", e->f.nops, nops + 1);
	}
	ck_u64("two commands skipped", stats_of(e).gce_skipped, s.gce_skipped + 2);
	ck_u64("0x16001000 reached VDEC_ALL", e->f.ops[e->f.nops - 1u].win, RWVC_WIN_VDEC_ALL);

	/* CMD_SEC_WRITE and an unknown command id are dropped (the kernel's secure case and default) */
	cmds_reset(e);
	cmd_set(c, 0, CMD_SEC_WRITE, 0x17020020u, 1, 0xffffffffu);
	cmd_set(c, 1, 200, 0x17020024u, 1, 0xffffffffu);
	cmd_count(c, 2);
	s = stats_of(e);
	ck_i64("sec/unknown skipped", gce_flush(e, 0x10c, VCU_VENC, 0, 0), 0);
	ck_u64("two more skipped", stats_of(e).gce_skipped, s.gce_skipped + 2);

	/* cmd_cnt >= VCODEC_CMDQ_CMD_MAX: clamped, still executed, -EINVAL (:1036-1041) */
	cmds_reset(e);
	cmd_count(c, 4096);
	s = stats_of(e);
	ck_i64("cmd_cnt overflow -> -EINVAL", gce_flush(e, 0x10d, VCU_VENC, 0, 0), -EINVAL);
	ck_u64("clamped to 2048", stats_of(e).gce_cmds, s.gce_cmds + 2048);

	/* 2048 writes fit exactly in one RWVC_REG_MAX_OPS batch */
	cmds_reset(e);
	{
		unsigned i;

		for (i = 0; i < 2048; i++)
			cmd_set(c, i, CMD_WRITE, 0x17020030u, i, 0xffffffffu);
	}
	cmd_count(c, 2048);
	e->f.ncalls = 0;
	e->f.nops = 0;
	/* cmd_cnt == VCODEC_CMDQ_CMD_MAX is already "overflow": clamp, execute, return -EINVAL */
	ck_i64("2048 writes -> -EINVAL but executed", gce_flush(e, 0x10e, VCU_VENC, 0, 0), -EINVAL);
	ck_u64("one regs call", e->f.ncalls, 1);
	ck_u64("batch of 2048 ops", e->f.call_count[0], 2048);
	ck_u64("last write value", win_word(&e->f, RWVC_WIN_VENC, 0x30), 2047);

	/* secure != 0 only selects the secure GCE thread in the kernel; the model executes it */
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x17020040u, 0x99u, 0xffffffffu);
	cmd_count(c, 1);
	ck_i64("secure flush", gce_flush(e, 0x10f, VCU_VENC, 0, 1), 0);
	ck_u64("secure register write", win_word(&e->f, RWVC_WIN_VENC, 0x40), 0x99u);

	env_fini(e);
}

static void t_gce_memmv(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;
	struct n2vcu_stats s;
	uint64_t pa, va, pa2, va2;

	ck("env_init", env_init(e) == 0);
	put_mem_obj(c, MEM_A, 0, 0x1000, 0, 0);
	ck_i64("PA alloc A", dev_ioctl(e, MTK_VCU_PA_ALLOCATION, MEM_A), 0);
	pa = get64(c, MEM_A + 16);
	va = get64(c, MEM_A + 24);
	put_mem_obj(c, MEM_B, 0, 0x1000, 0, 0);
	ck_i64("PA alloc B", dev_ioctl(e, MTK_VCU_PA_ALLOCATION, MEM_B), 0);
	pa2 = get64(c, MEM_B + 16);
	va2 = get64(c, MEM_B + 24);

	/* memory -> memory: :752-772 */
	put32(c, (uint32_t)va, 0x11223344u);
	put32(c, (uint32_t)va2, 0xffffffffu);
	cmds_reset(e);
	cmd_set(c, 0, CMD_MEM_MV, pa, pa2, 0);
	cmd_count(c, 1);
	ck_i64("MEM_MV mem->mem", gce_flush(e, 0x200, VCU_VENC, 0, 0), 0);
	ck_u64("MEM_MV copied", get32(c, (uint32_t)va2), 0x11223344u);

	/* register -> memory */
	e->f.reg[RWVC_WIN_VENC][0x44 / 4] = 0xa5a5a5a5u;
	cmds_reset(e);
	cmd_set(c, 0, CMD_MEM_MV, 0x17020044u, pa2 + 4u, 0);
	cmd_count(c, 1);
	ck_i64("MEM_MV reg->mem", gce_flush(e, 0x201, VCU_VENC, 0, 0), 0);
	ck_u64("MEM_MV register value", get32(c, (uint32_t)va2 + 4u), 0xa5a5a5a5u);

	/* the destination must be a PA page in the kernel (:757-763), so reg <- mem is skipped */
	s = stats_of(e);
	cmds_reset(e);
	cmd_set(c, 0, CMD_MEM_MV, pa, 0x17020048u, 0);
	cmd_count(c, 1);
	ck_i64("MEM_MV mem->reg skipped", gce_flush(e, 0x202, VCU_VENC, 0, 0), 0);
	ck_u64("mem->reg counted as skipped", stats_of(e).gce_skipped, s.gce_skipped + 1);
	ck_u64("register untouched", win_word(&e->f, RWVC_WIN_VENC, 0x48), 0);

	/* unknown source and destination are skipped, not errors */
	s = stats_of(e);
	cmds_reset(e);
	cmd_set(c, 0, CMD_MEM_MV, 0xdead0000u, pa2, 0);
	cmd_set(c, 1, CMD_MEM_MV, pa, 0xdead1000u, 0);
	cmd_count(c, 2);
	ck_i64("MEM_MV bad src/dst", gce_flush(e, 0x203, VCU_VENC, 0, 0), 0);
	ck_u64("two skipped", stats_of(e).gce_skipped, s.gce_skipped + 2);

	/* CMD_POLL_ADDR on a register -> RWVC_OP_POLL */
	cmds_reset(e);
	cmd_set(c, 0, CMD_POLL_ADDR, 0x1702004cu, 0x8u, 0x8u);
	cmd_count(c, 1);
	ck_i64("POLL_ADDR reg", gce_flush(e, 0x204, VCU_VENC, 0, 0), 0);
	ck_u64("POLL_ADDR op", e->f.ops[e->f.nops - 1].op, RWVC_OP_POLL);
	/* CMD_POLL_ADDR on a PA page: bounded guest-memory poll */
	put32(c, (uint32_t)va + 8u, 0x10u);
	cmds_reset(e);
	cmd_set(c, 0, CMD_POLL_ADDR, pa + 8u, 0x10u, 0x10u);
	cmd_count(c, 1);
	ck_i64("POLL_ADDR mem", gce_flush(e, 0x205, VCU_VENC, 0, 0), 0);
	n2vcu_set_poll_timeout_ms(e->v, 0);
	put32(c, (uint32_t)va + 8u, 0);
	cmds_reset(e);
	cmd_set(c, 0, CMD_POLL_ADDR, pa + 8u, 0x10u, 0x10u);
	cmd_count(c, 1);
	ck_i64("POLL_ADDR mem timeout", gce_flush(e, 0x206, VCU_VENC, 0, 0), -ETIMEDOUT);

	env_fini(e);
}

static void t_gce_validation(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;

	ck("env_init", env_init(e) == 0);

	/* cmds_user_ptr == 0 -> -EINVAL (:917-919) */
	cmds_reset(e);
	cmd_count(c, 1);
	put64(c, CMDQ_A, 0);
	put64(c, CMDQ_A + 8, 0x300);
	put32(c, CMDQ_A + 0x14, VCU_VENC);
	put32(c, CMDQ_A + 0x18, 0);
	ck_i64("cmds_user_ptr 0 -> -EINVAL", dev_ioctl(e, MTK_VCU_GCE_SET_CMD_FLUSH, CMDQ_A), -EINVAL);

	/* codec_type/core_id validation (:925-931): 1 VDEC thread, 2 VENC */
	cmds_reset(e);
	cmd_count(c, 0);
	ck_i64("codec_type 2 -> -EINVAL", gce_flush(e, 0x300, 2, 0, 0), -EINVAL);
	ck_i64("VDEC core 1 -> -EINVAL", gce_flush(e, 0x300, VCU_VDEC, 1, 0), -EINVAL);
	ck_i64("VDEC core 0", gce_flush(e, 0x300, VCU_VDEC, 0, 0), 0);
	ck_i64("VENC core 1", gce_flush(e, 0x301, VCU_VENC, 1, 0), 0);
	ck_i64("VENC core 2 -> -EINVAL", gce_flush(e, 0x301, VCU_VENC, 2, 0), -EINVAL);
	n2vcu_set_gce_threads(e->v, 2, 1);
	ck_i64("VDEC core 1 after set_gce_threads", gce_flush(e, 0x300, VCU_VDEC, 1, 0), 0);
	n2vcu_set_gce_threads(e->v, 1, 2);

	/* VCU_GCE_WAIT_CALLBACK: unknown handle -> -EINVAL (:1126-1128) */
	ck_i64("wait unknown handle -> -EINVAL", gce_wait(e, 0x9999, VCU_VENC), -EINVAL);

	/* one flush gives exactly one callback; a second wait times out */
	cmds_reset(e);
	cmd_count(c, 0);
	ck_i64("flush for callback", gce_flush(e, 0x302, VCU_VENC, 0, 0), 0);
	ck_i64("wait callback", gce_wait(e, 0x302, VCU_VENC), 0);
	n2vcu_set_callback_timeout_ms(e->v, 0);
	ck_i64("second wait -> -ETIMEDOUT", gce_wait(e, 0x302, VCU_VENC), -ETIMEDOUT);

	/* The callback is synchronous here, so flush_done > 0 when the wait starts; the kernel's
	 * wait_event predicate is the same for both wait queues, so even a wait that names the other
	 * codec returns immediately at that point (it would only block if the callback had not run). */
	ck_i64("flush with a completed callback", gce_flush(e, 0x303, VCU_VENC, 0, 0), 0);
	ck_i64("VDEC wait after the callback returned", gce_wait(e, 0x303, VCU_VDEC), 0);

	/* abort breaks the callback wait */
	n2vcu_abort(e->v);
	ck_i64("aborted wait -> -EINTR", gce_wait(e, 0x303, VCU_VENC), -EINTR);
	env_fini(e);
}

static void t_gce_order(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;

	ck("env_init", env_init(e) == 0);
	/* [WRITE, WAIT_EVENT, WRITE] must reach the back end as regs, wait_irq, regs, in order */
	e->f.irq_fire[RWVC_IRQ_VENC] = 1;
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x17020010u, 0x1u, 0xffffffffu);
	cmd_set(c, 1, CMD_WAIT_EVENT, 0, VENC_EOF, 0);
	cmd_set(c, 2, CMD_WRITE, 0x17020014u, 0x2u, 0xffffffffu);
	cmd_count(c, 3);
	e->f.ncalls = 0;
	e->f.nev = 0;
	ck_i64("ordered flush", gce_flush(e, 0x400, VCU_VENC, 0, 0), 0);
	ck_u64("two regs calls", e->f.ncalls, 2);
	ck_u64("first batch one op", e->f.call_count[0], 1);
	ck_u64("second batch one op", e->f.call_count[1], 1);
	ck_u64("events R I R", (uint64_t)(uint8_t)e->f.events[0], 'R');
	ck_u64("event 2", (uint64_t)(uint8_t)e->f.events[1], 'I');
	ck_u64("event 3", (uint64_t)(uint8_t)e->f.events[2], 'R');
	ck_u64("first write landed", win_word(&e->f, RWVC_WIN_VENC, 0x10), 1);
	ck_u64("second write landed", win_word(&e->f, RWVC_WIN_VENC, 0x14), 2);
	env_fini(e);
}

/* ---------------------------------------------------------------- VENC power around a GCE job */

static void t_gce_power(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;

	ck("env_init", env_init(e) == 0);

	/* mtk_vcu.c:980-1000: vcu_gce_set_cmd_flush() calls venc_encode_prepare() for the core when
	 * its job count was 0, and the flush callback (:806-830) unprepares it when the count drops
	 * back to 0.  The daemon sends no VCU_IPIMSG_ENC_POWER_ON in GCE mode (opus-venc fact), so
	 * this is the only place the encoder blocks get powered for an encode.  The model runs the
	 * list synchronously: power on -> run -> power off, around the one job. */
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x17020050u, 0x1u, 0xffffffffu);
	cmd_count(c, 1);
	e->f.power_calls = 0;
	ck_i64("VENC core 0 flush", gce_flush(e, 0x600, VCU_VENC, 0, 0), 0);
	ck_u64("two power calls", e->f.power_calls, 2);
	ck_u64("power on block VENC", e->f.pw[0].block, RWVC_BLK_VENC);
	ck_u64("power on", (uint64_t)(unsigned)e->f.pw[0].on, 1);
	ck_u64("power off block VENC", e->f.pw[1].block, RWVC_BLK_VENC);
	ck_u64("power off", (uint64_t)(unsigned)e->f.pw[1].on, 0);
	ck_u64("list ran while powered", win_word(&e->f, RWVC_WIN_VENC, 0x50), 1);

	/* core 1 is a separate block (mtk_vcu.c:996-997). */
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x17820050u, 0x2u, 0xffffffffu);
	cmd_count(c, 1);
	e->f.power_calls = 0;
	ck_i64("VENC core 1 flush", gce_flush(e, 0x601, VCU_VENC, 1, 0), 0);
	ck_u64("two power calls core 1", e->f.power_calls, 2);
	ck_u64("power on block VENC_C1", e->f.pw[0].block, RWVC_BLK_VENC_C1);
	ck_u64("power off block VENC_C1", e->f.pw[1].block, RWVC_BLK_VENC_C1);
	ck_u64("core 1 register written", win_word(&e->f, RWVC_WIN_VENC_C1, 0x50), 2);

	/* A decoder list must not power an encoder block (:994 tests the codec type). */
	cmds_reset(e);
	cmd_count(c, 0);
	e->f.power_calls = 0;
	ck_i64("VDEC flush", gce_flush(e, 0x602, VCU_VDEC, 0, 0), 0);
	ck_u64("no power calls for VDEC", e->f.power_calls, 0);

	/* A list that fails still powers on/off (the kernel's timeout path ends in the same flush
	 * callback, vcu_gce_timeout_callback -> vcu_gce_flush_callback) and still leaves exactly one
	 * callback for VCU_GCE_WAIT_CALLBACK, so the daemon never hangs after a hardware error. */
	n2vcu_set_irq_timeout_ms(e->v, 0);
	cmds_reset(e);
	cmd_set(c, 0, CMD_WAIT_EVENT, 0, VENC_EOF, 0);
	cmd_count(c, 1);
	e->f.power_calls = 0;
	ck_i64("failing VENC flush", gce_flush(e, 0x603, VCU_VENC, 0, 0), -ETIMEDOUT);
	ck_u64("powered around the failing list", e->f.power_calls, 2);
	ck_u64("power off after the failure", (uint64_t)(unsigned)e->f.pw[1].on, 0);
	ck_i64("callback after a failed flush", gce_wait(e, 0x603, VCU_VENC), 0);
	n2vcu_set_callback_timeout_ms(e->v, 0);
	ck_i64("exactly one callback", gce_wait(e, 0x603, VCU_VENC), -ETIMEDOUT);

	env_fini(e);
}

/* ---------------------------------------------------------------- VENC bitstream mirror refresh */

/*
 * The vendor encoder writes the frame at the bitstream buffer start and VENC_PrependHeader then
 * memmoves it up on the CPU with no invalidate (libvcodec_utility.so 0x228d0, memmove 0x2295c;
 * opus-hevc HIGH).  On Android the buffer is coherent DMA memory; here the guest sees a copy, so
 * the model refreshes it after the VENC GCE list (0x064 carries the bitstream pa >> 4,
 * VENC_PROTOCOL.md).  Without it the daemon returns headers + stale bytes for H.264 and HEVC.
 */
static void t_gce_mirror(void)
{
	struct env *e = &g_env;
	struct n2a32_cpu *c = &e->cpu;
	struct n2vcu_stats s0;
	struct fhw_dma *d;
	uint64_t pa, va, pa2, va2;
	uint32_t i, handle = 0, rpa = 0, rguest = 0;
	struct fhw_dma *reg;

	ck("env_init", env_init(e) == 0);

	/* A buffer this model allocated (the daemon's VCU_PA_ALLOCATION path). */
	put_mem_obj(c, MEM_A, 0, 0x1000, 0, 0);
	ck_i64("PA_ALLOCATION for the mirror test", dev_ioctl(e, MTK_VCU_PA_ALLOCATION, MEM_A), 0);
	pa = get64(c, MEM_A + 16);
	va = get64(c, MEM_A + 24);
	d = fhw_buf_for_pa(&e->f, (uint32_t)pa);
	ck("mirror buffer found", d != NULL && d->bytes == 0x1000u);
	for (i = 0; i < 0x1000u; i++) {
		n2a32_st8(c, (uint32_t)va + i, 0xaau);            /* the stale guest copy */
		if (d)
			d->buf[i] = (uint8_t)(i * 7u + 3u);       /* what the encoder wrote */
	}
	s0 = stats_of(e);
	e->f.irq_fire[RWVC_IRQ_VENC] = 1;
	cmds_reset(e);
	/* 0x068 is the bitstream size, 0x064 the base (VENC_PROTOCOL.md section 3). */
	cmd_set(c, 0, CMD_WRITE, 0x17020068u, 0x2000u, 0xffffffffu);
	cmd_set(c, 1, CMD_WRITE, 0x17020064u, pa >> 4, 0xffffffffu);
	cmd_set(c, 2, CMD_WAIT_EVENT, 0, VENC_EOF, 0);
	cmd_count(c, 3);
	ck_i64("VENC list with the bitstream base", gce_flush(e, 0x700, VCU_VENC, 0, 0), 0);
	ck_u64("one bitstream sync counted", stats_of(e).gce_bitstream_syncs,
	       s0.gce_bitstream_syncs + 1);
	ck_u64("bitstream bytes counted", stats_of(e).gce_bitstream_bytes,
	       s0.gce_bitstream_bytes + 0x1000u);
	ck_u64("guest byte 0 refreshed", n2a32_ld8(c, (uint32_t)va), d ? d->buf[0] : 0);
	ck_u64("guest byte 0x123 refreshed", n2a32_ld8(c, (uint32_t)va + 0x123u),
	       d ? d->buf[0x123] : 0);
	ck_u64("guest last byte refreshed", n2a32_ld8(c, (uint32_t)va + 0xfffu),
	       d ? d->buf[0xfff] : 0);

	/* Only the bitstream buffer is refreshed: 0x06c (source luma) is written by the CPU before
	 * the trigger, so its guest copy must stay as the guest left it. */
	put_mem_obj(c, MEM_A, 0, 0x1000, 0, 0);
	ck_i64("PA_ALLOCATION for the source test", dev_ioctl(e, MTK_VCU_PA_ALLOCATION, MEM_A), 0);
	pa2 = get64(c, MEM_A + 16);
	va2 = get64(c, MEM_A + 24);
	reg = fhw_buf_for_pa(&e->f, (uint32_t)pa2);
	if (reg)
		memset(reg->buf, 0x77, 0x1000);
	for (i = 0; i < 0x1000u; i++)
		n2a32_st8(c, (uint32_t)va2 + i, 0x11);
	s0 = stats_of(e);
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x1702006cu, pa2 >> 4, 0xffffffffu);
	cmd_count(c, 1);
	ck_i64("VENC list with a source plane", gce_flush(e, 0x701, VCU_VENC, 0, 0), 0);
	ck_u64("no sync for 0x06c", stats_of(e).gce_bitstream_syncs, s0.gce_bitstream_syncs);
	ck_u64("source guest byte 0 untouched", n2a32_ld8(c, (uint32_t)va2), 0x11);
	ck_u64("source guest last byte untouched", n2a32_ld8(c, (uint32_t)va2 + 0xfffu), 0x11);

	/* Core 1 has its own window (0x17820000) but the same 0x064 register. */
	if (d)
		memset(d->buf, 0x5c, 0x1000);
	for (i = 0; i < 0x1000u; i++)
		n2a32_st8(c, (uint32_t)va + i, 0x22);
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x17820064u, pa >> 4, 0xffffffffu);
	cmd_count(c, 1);
	ck_i64("VENC core 1 list", gce_flush(e, 0x702, VCU_VENC, 1, 0), 0);
	ck_u64("core 1 guest byte 0 refreshed", n2a32_ld8(c, (uint32_t)va), d ? d->buf[0] : 0);
	ck_u64("core 1 guest last byte refreshed", n2a32_ld8(c, (uint32_t)va + 0xfffu),
	       d ? d->buf[0xfff] : 0);

	/* A decoder list does not refresh anything (the kernel's split is by codec type, and the
	 * VDEC core never runs VENC_PrependHeader). */
	for (i = 0; i < 0x1000u; i++)
		n2a32_st8(c, (uint32_t)va + i, 0x33);
	s0 = stats_of(e);
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x16000064u, pa >> 4, 0xffffffffu);
	cmd_count(c, 1);
	ck_i64("VDEC list with a 0x064 write", gce_flush(e, 0x703, VCU_VDEC, 0, 0), 0);
	ck_u64("VDEC list made no sync", stats_of(e).gce_bitstream_syncs, s0.gce_bitstream_syncs);
	ck_u64("VDEC guest byte 0 untouched", n2a32_ld8(c, (uint32_t)va), 0x33);

	/* An offset that merely ends in 0x064 is not the bitstream register: only the exact VENC
	 * offset 0x064 (window-relative) counts. */
	for (i = 0; i < 0x1000u; i++)
		n2a32_st8(c, (uint32_t)va + i, 0x66);
	s0 = stats_of(e);
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x17021064u, pa >> 4, 0xffffffffu);
	cmd_count(c, 1);
	ck_i64("VENC list with offset 0x1064", gce_flush(e, 0x706, VCU_VENC, 0, 0), 0);
	ck_u64("0x1064 made no sync", stats_of(e).gce_bitstream_syncs, s0.gce_bitstream_syncs);
	ck_u64("0x1064 left the guest alone", n2a32_ld8(c, (uint32_t)va), 0x66);

	/* An address no buffer covers is not a failure (the kernel would simply have written the
	 * register; the refresh is a coherence repair, not part of the ABI). */
	s0 = stats_of(e);
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x17020064u, 0x1234567u, 0xffffffffu);
	cmd_count(c, 1);
	ck_i64("unknown bitstream pa", gce_flush(e, 0x704, VCU_VENC, 0, 0), 0);
	ck_u64("unknown pa made no sync", stats_of(e).gce_bitstream_syncs, s0.gce_bitstream_syncs);

	/* A buffer registered by the AP outside this model (V41's n2vc_dma.c): lookup_pa() is the
	 * second source of (guest, bytes), and the sync still goes through hw->dma_rw. */
	ck_i64("raw fake dma_alloc", e->f.hw.dma_alloc(e->f.hw.ctx, 0x1000, 0, &handle, &rpa), 0);
	ck_i64("register the raw buffer", n2vc_dma_guest_map(&e->f.hw, e->mem, handle, 0x1000,
							    &rguest), 0);
	dreg_set_pa(handle, rpa);
	reg = fhw_buf_for_pa(&e->f, rpa);
	if (reg)
		memset(reg->buf, 0x44, 0x1000);
	for (i = 0; i < 0x1000u; i++)
		n2a32_st8(c, rguest + i, 0x99);
	s0 = stats_of(e);
	cmds_reset(e);
	cmd_set(c, 0, CMD_WRITE, 0x17020064u, (uint64_t)rpa >> 4, 0xffffffffu);
	cmd_count(c, 1);
	ck_i64("VENC list with an AP-registered buffer", gce_flush(e, 0x705, VCU_VENC, 0, 0), 0);
	ck_u64("AP buffer sync counted", stats_of(e).gce_bitstream_syncs,
	       s0.gce_bitstream_syncs + 1);
	ck_u64("AP buffer guest byte 0 refreshed", n2a32_ld8(c, rguest), 0x44);
	ck_u64("AP buffer guest last byte refreshed", n2a32_ld8(c, rguest + 0xfffu), 0x44);
	ck_i64("unmap the raw buffer", n2vc_dma_guest_unmap(&e->f.hw, e->mem, rguest), 0);
	ck_i64("free the raw buffer", e->f.hw.dma_free(e->f.hw.ctx, handle), 0);

	env_fini(e);
}

/* ---------------------------------------------------------------- T02's fake back end */

static void t_t02_fake(void)
{
	struct n2a32_mem *mem;
	struct n2a32_cpu cpu;
	struct n2vc_hw hw;
	struct n2vcu *v;
	const char *tmp = getenv("N2V40_TMP");
	char path[512], line[512], script[512];
	FILE *fp;
	uint32_t pa = 0, va = 0;
	int found_w = 0, found_poll = 0, found_irq = 0;

	if (!tmp)
		tmp = "/tmp";
	snprintf(path, sizeof(path), "%s/v40_t02_record.txt", tmp);
	snprintf(script, sizeof(script), "%s/v40_t02_script.txt", tmp);
	fp = fopen(script, "w");
	ck("script file", fp != NULL);
	if (!fp)
		return;
	fprintf(fp, "after write VENC 0x0010 0x00000001 -> set VENC 0x0018 0x00000004\n");
	fprintf(fp, "irq 0 fires 0 ms after write VENC 0x0010 0x00000001\n");
	fclose(fp);

	/* T02's fake gates every window on its power block and counts a violation otherwise. */
	ck("open T02 fake", n2vc_hw_open_fake(&hw, path) == 0);
	ck("script loaded", n2vc_hw_fake_script(&hw, script) == 0);
	ck("power VENC", hw.power(hw.ctx, RWVC_BLK_VENC, 1) == 0);

	mem = n2a32_mem_create();
	ck("mem", mem != NULL);
	ck("guest map", n2a32_mem_map(mem, GB, 0x20000, 1) == 0);
	n2a32_cpu_init(&cpu, mem);
	v = n2vcu_create(mem, &hw);
	ck("vcu over T02 fake", v != NULL);
	if (!v)
		return;
	g_env.mem = mem;
	g_env.cpu = cpu;
	g_env.v = v;
	g_env.dev = n2vcu_dev(v);
	g_env.opened = 1;
	g_env.f = (struct fhw){ 0 };
	ck("open dev", g_env.dev->open(g_env.dev->ctx, 2) == 0);

	/* write VENC 0x10, poll 0x18 for 4 (the write triggers the rule), then wait the VENC IRQ */
	cmds_reset(&g_env);
	cmd_set(&cpu, 0, CMD_WRITE, 0x17020010u, 0x1u, 0xffffffffu);
	cmd_set(&cpu, 1, CMD_POLL_REG, 0x17020018u, 0x4u, 0x4u);
	cmd_set(&cpu, 2, CMD_WAIT_EVENT, 0, VENC_EOF, 0);
	cmd_count(&cpu, 3);
	ck_i64("flush through T02's fake", gce_flush(&g_env, 0x500, VCU_VENC, 0, 0), 0);
	ck_u64("no fake violations", n2vc_hw_fake_violations(&hw), 0);

	/* DMA through T02's fake: pa must be inside RW_CLAIM_VCODEC */
	put_mem_obj(&cpu, MEM_A, 0, 0x1000, 0, 0);
	ck_i64("T02 MVA alloc", dev_ioctl(&g_env, MTK_VCU_MVA_ALLOCATION, MEM_A), 0);
	pa = (uint32_t)get64(&cpu, MEM_A + 16);
	va = (uint32_t)get64(&cpu, MEM_A + 24);
	ck("T02 pa inside RW_CLAIM_VCODEC", pa >= RW_CLAIM_VCODEC_PA &&
					     (uint64_t)pa + 0x1000 <=
					     (uint64_t)RW_CLAIM_VCODEC_PA + RW_CLAIM_VCODEC_BYTES);
	put32(&cpu, va, 0x13572468u);
	put_mem_obj(&cpu, MEM_A, pa, 0x1000, pa, va);
	ck_i64("T02 cache flush", dev_ioctl(&g_env, MTK_VCU_CACHE_FLUSH_BUFF, MEM_A), 0);
	{
		struct n2vc_hw_fake_stats fs;

		n2vc_hw_fake_stats(&hw, &fs);
		ck_u64("T02 fake writes seen", fs.writes >= 1, 1);
		ck_u64("T02 fake polls seen", fs.polls, 1);
		ck_u64("T02 fake irq waits", fs.irq_waits, 1);
		ck_u64("T02 fake dma allocs", fs.dma_allocs, 1);
	}

	fp = fopen(path, "r");
	ck("record file", fp != NULL);
	if (fp) {
		while (fgets(line, sizeof(line), fp)) {
			if (strstr(line, "W VENC 0x0010 0x00000001"))
				found_w = 1;
			if (strstr(line, "POLL VENC 0x0018 0x00000004 mask 0x00000004 -> ok"))
				found_poll = 1;
			if (strstr(line, "IRQ wait 0"))
				found_irq = 1;
		}
		fclose(fp);
	}
	ck("record: write", found_w);
	ck("record: poll ok", found_poll);
	ck("record: irq wait", found_irq);
	g_env.dev->close(g_env.dev->ctx);
	n2vcu_destroy(v);
	n2a32_mem_destroy(mem);
	g_env.v = NULL;
	hw.close(hw.ctx);
}

/* ---------------------------------------------------------------- main */

int main(int argc, char **argv)
{
	(void)argc;
	(void)argv;

	t_layout();
	t_requests();
	t_ipi();
	t_ipi_thread();
	t_alloc();
	t_mmap_regs();
	t_mmap_dma();
	t_log();
	t_log_block();
	t_log_destroy();
	t_gce_cmds();
	t_gce_memmv();
	t_gce_validation();
	t_gce_order();
	t_gce_power();
	t_gce_mirror();
	t_t02_fake();

	printf("SUMMARY %u %u\n", g_checks - g_fails, g_checks);
	return g_fails ? 1 : 0;
}
